content.query:
let openIncidents = toscalar(SecurityIncident | summarize arg_max(TimeGenerated, Status) by IncidentNumber | where Status in ("New","Active") | count);
let totalAlerts = toscalar(SecurityAlert | count);
let activeSources = toscalar(Heartbeat | where TimeGenerated > ago(15m) | summarize dcount(Computer));
let signinCount = toscalar(union isfuzzy=true (SigninLogs), (AADNonInteractiveUserSignInLogs) | count);
let todayGB = toscalar(Usage | where TimeGenerated > startofday(now()) | where IsBillable == true | summarize round(sum(Quantity)/1024, 3));
print Metric = "🚨 Open incidents", Value = openIncidents, Detail = "New + Active"
| union (print Metric = "🔔 Total alerts", Value = totalAlerts, Detail = "SecurityAlert, all-time")
| union (print Metric = "💓 Active sources", Value = activeSources, Detail = "heartbeat in last 15m")
| union (print Metric = "🪪 Sign-ins", Value = signinCount, Detail = "selected window")
| union (print Metric = "💰 GB today", Value = todayGB, Detail = "of 1 GB/day cap")
